{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "Edm3dBm9_GY2uVx35CBGpQ",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city looms ahead.",
      "visual_description": "A vast ruined city under a twilight sky, crumbled walls and broken towers, with old royal banners hanging torn from spires.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "The castle gates are sealed.",
      "visual_description": "Massive iron gates rusted shut, vines and rubble blocking the entrance, faint light seeps through cracks.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "A cursed tower watches over the square.",
      "visual_description": "A leaning tower with a spiral staircase and glowing sigils, its shadow stretching across a cobblestone square.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "Rumors of a dragon echo in the alley.",
      "visual_description": "Narrow alley with shattered windows and scorch marks, a distant roar reverberates off stone walls.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Old royal banners flutter above the plaza.",
      "visual_description": "A plaza lined with broken flagpoles, faded banners bearing a crest of a sun and crown, wind whips through tattered cloth.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "Frightened townspeople huddle in the market.",
      "visual_description": "A collapsed market with overturned stalls, people clutching each other, eyes wide with fear, shadows of patrols passing.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "Armored patrols march through the streets.",
      "visual_description": "A column of figures in dark plate armor, visors down, weapons drawn, marching in unison down a narrow street.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "A magic door appears in the wall.",
      "visual_description": "A smooth stone wall where a door suddenly forms, its surface shimmering with runes, handle glowing faintly.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The sleeping tax collector blocks the archive.",
      "visual_description": "A dusty archive room, a figure slumped over a desk using a ledger as a pillow, stamped papers stuck to sleeves.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver swims through a mirror.",
      "visual_description": "A tall cracked mirror in an abandoned hall, the glass diver steps into its surface, ripples spreading like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Mara reads a map in the patrol barracks.",
      "visual_description": "A dimly lit barracks with bunks and weapon racks, Mara unrolls a map on a table, compass in hand, tin fox watches.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 12,
      "caption": "The oracle lamp warns of a trap.",
      "visual_description": "A narrow corridor with pressure plates on the floor, the lamp's flame flickers and a single eye appears, speaking urgently.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "Piles of broken stone and twisted metal, a small clockwork fox picks its way over debris, blue eyes scanning.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector is carried to safety.",
      "visual_description": "A collapsing room, Mara and the glass diver lift the still-sleeping figure in a chair, papers trailing behind.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Patrols converge on the escape route.",
      "visual_description": "A wide avenue, armored figures approaching from both ends, their footsteps echoing, the group pressed against a wall.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver creates a mirror path.",
      "visual_description": "The glass diver touches a window, its surface turns liquid, a shimmering path extends across the street to a bridge.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The group crosses the escape bridge.",
      "visual_description": "A long stone bridge over a dry riverbed, cracked railings, the group hurries across as patrols reach the near end.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They reach the far side as the bridge crumbles.",
      "visual_description": "The bridge collapses behind them, dust rising, the ruined city now across a gap, the group safe on a green hill.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

